import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import {
  buildFlashcards,
  buildQuiz,
  createRemoteTutor,
  createStaticTutor,
  summarizeProgress,
  type QuizQuestion,
  type TutorAnswer,
} from "@cas/education-core";
import {
  previewUrl,
  REGISTRY,
  REGISTRY_SOURCES,
  REGISTRY_SPECIMENS,
  requireSpecimen,
} from "../content";
import { appStore } from "../state/app-store";
import { useVanillaStore } from "../lib/use-vanilla-store";
import { navigateToStructure, nextTabIndex } from "../lib/navigation";
import { usePersistence } from "../persistence/PersistenceProvider";
import { effectiveReducedMotion, useSystemReducedMotion } from "../lib/media";
import { useSlidingPill } from "../lib/use-sliding-pill";
import {
  createSpringValue,
  projectMomentum,
  rubberband,
  SPRING_MOMENTUM,
  SPRING_UI,
} from "../lib/spring";
import { IconArrowUpRight, IconCheck, IconX } from "../components/Icons";

type TabId = "cards" | "quiz" | "tutor" | "progress";

const TABS: Array<{ id: TabId; label: string }> = [
  { id: "cards", label: "Flashcards" },
  { id: "quiz", label: "Quiz" },
  { id: "tutor", label: "Ask" },
  { id: "progress", label: "Progress" },
];

export function LearnPage() {
  const specimenId = useVanillaStore(appStore, (state) => state.specimenId);
  const reduceMotionSetting = useVanillaStore(appStore, (state) => state.settings.reduceMotion);
  const systemReduced = useSystemReducedMotion();
  const reduceMotion = effectiveReducedMotion(reduceMotionSetting, systemReduced);
  const [tab, setTab] = useState<TabId>("cards");
  const specimen = requireSpecimen(specimenId);
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const tabIndex = Math.max(
    0,
    TABS.findIndex((entry) => entry.id === tab),
  );
  const tabPill = useSlidingPill<HTMLButtonElement>(tabIndex, reduceMotion);

  function onTabKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const next = nextTabIndex(event.key, index, TABS.length);
    if (next === null) return;
    event.preventDefault();
    const target = TABS[next];
    if (target) {
      setTab(target.id);
      tabRefs.current[next]?.focus();
    }
  }

  return (
    <div className="page page--learn">
      <header className="page-header">
        <div>
          <p className="eyebrow">Offline study</p>
          <h1>Learn from cited facts</h1>
          <p className="lede">
            Flashcards, questions, and the study helper use only the reviewed statements in this
            registry. Unsupported questions are refused rather than guessed.
          </p>
        </div>
        <label className="field field--inline">
          <span>Specimen</span>
          <select
            value={specimen.id}
            onChange={(event) => appStore.getState().selectSpecimen(event.target.value)}
          >
            {REGISTRY_SPECIMENS.map((candidate) => (
              <option key={candidate.id} value={candidate.id}>
                {candidate.name}
              </option>
            ))}
          </select>
        </label>
      </header>

      <div className="learning-summary">
        <div>
          <p className="eyebrow">{specimen.name}</p>
          <p className="muted small">{specimen.summary}</p>
        </div>
        <MasteryBadge
          specimenId={specimen.id}
          structureCount={specimen.structures.length}
          accent={specimen.accent}
        />
      </div>

      <div className="tabs" role="tablist" aria-label="Learning modes" ref={tabPill.containerRef}>
        <span className="spring-pill" aria-hidden="true" ref={tabPill.pillRef} />
        {TABS.map((entry, index) => {
          const registerPillItem = tabPill.registerItem(index);
          return (
            <button
              key={entry.id}
              ref={(element) => {
                tabRefs.current[index] = element;
                registerPillItem(element);
              }}
              type="button"
              role="tab"
              id={`tab-${entry.id}`}
              aria-selected={tab === entry.id}
              aria-controls={`panel-${entry.id}`}
              tabIndex={tab === entry.id ? 0 : -1}
              className={tab === entry.id ? "tab tab--active" : "tab"}
              onClick={() => setTab(entry.id)}
              onKeyDown={(event) => onTabKeyDown(event, index)}
            >
              {entry.label}
            </button>
          );
        })}
      </div>

      <div
        role="tabpanel"
        id={`panel-${tab}`}
        aria-labelledby={`tab-${tab}`}
        tabIndex={0}
        className="tab-panel"
      >
        {tab === "cards" && (
          <FlashcardsPanel key={specimen.id} specimenId={specimen.id} reduceMotion={reduceMotion} />
        )}
        {tab === "quiz" && <QuizPanel key={specimen.id} specimenId={specimen.id} />}
        {tab === "tutor" && <TutorPanel key={specimen.id} specimenId={specimen.id} />}
        {tab === "progress" && <ProgressPanel />}
      </div>
    </div>
  );
}

function MasteryBadge({
  specimenId,
  structureCount,
  accent,
}: {
  specimenId: string;
  structureCount: number;
  accent: string;
}) {
  const profile = useVanillaStore(appStore, (state) => state.profile);
  const summary = summarizeProgress(profile, specimenId, structureCount);
  const radius = 21;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference * (1 - summary.mastery / 100);

  return (
    <div className="mastery-badge" style={{ "--ring-accent": accent } as CSSProperties}>
      <div className="mastery-badge__ring" aria-hidden="true">
        <svg width="52" height="52" viewBox="0 0 52 52">
          <circle className="mastery-badge__track" cx="26" cy="26" r={radius} />
          <circle
            className="mastery-badge__arc"
            cx="26"
            cy="26"
            r={radius}
            strokeDasharray={circumference.toFixed(2)}
            strokeDashoffset={offset.toFixed(2)}
          />
        </svg>
      </div>
      <div className="mastery-badge__text">
        <span className="eyebrow">Mastery</span>
        <strong>{summary.mastery}%</strong>
        <span className="muted small">
          {summary.structuresViewed}/{summary.structuresTotal} structures ·{" "}
          {summary.questionsCorrect}/{summary.questionsAnswered} correct
        </span>
      </div>
    </div>
  );
}

function FlashcardsPanel({
  specimenId,
  reduceMotion,
}: {
  specimenId: string;
  reduceMotion: boolean;
}) {
  const specimen = requireSpecimen(specimenId);
  const cards = useMemo(() => buildFlashcards(REGISTRY, specimen), [specimen]);
  const [index, setIndex] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const card = cards[index];
  const cardRef = useRef<HTMLDivElement>(null);
  const [spring] = useState(() => createSpringValue(0));
  const dragRef = useRef<{
    active: boolean;
    committed: boolean;
    pointerId: number;
    startX: number;
    startY: number;
    currentX: number;
    width: number;
    history: Array<{ x: number; t: number }>;
  } | null>(null);

  useEffect(() => {
    const unsub = spring.subscribe((x) => {
      const node = cardRef.current;
      if (!node) return;
      if (Math.abs(x) < 0.05) {
        node.style.transform = "";
      } else {
        const tilt = x * 0.022;
        node.style.transform = `translate3d(${x.toFixed(2)}px, 0, 0) rotate(${tilt.toFixed(2)}deg)`;
      }
    });
    return () => {
      unsub();
      spring.stop();
    };
  }, [spring]);

  function go(delta: number, entryOffset = 0, releaseVelocity = 0) {
    if (cards.length === 0) return;
    setIndex((current) => (current + delta + cards.length) % cards.length);
    setFlipped(false);
    if (!reduceMotion && entryOffset !== 0) {
      spring.setImmediate(entryOffset);
      spring.setTarget(0, { config: SPRING_MOMENTUM, velocity: releaseVelocity });
    } else {
      spring.setImmediate(0);
    }
  }

  function onPointerDown(event: PointerEvent<HTMLDivElement>) {
    if (event.button !== 0) return;
    const target = event.target as HTMLElement | null;
    if (target?.closest("button, a, summary")) return;
    const liveX = spring.getValue();
    spring.stop();
    const rect = cardRef.current?.getBoundingClientRect();
    dragRef.current = {
      active: true,
      committed: false,
      pointerId: event.pointerId,
      startX: event.clientX - liveX,
      startY: event.clientY,
      currentX: liveX,
      width: rect?.width ?? 420,
      history: [{ x: liveX, t: performance.now() }],
    };
  }

  function onPointerMove(event: PointerEvent<HTMLDivElement>) {
    const drag = dragRef.current;
    if (!drag || !drag.active || event.pointerId !== drag.pointerId) return;
    const rawDx = event.clientX - drag.startX;
    const dy = event.clientY - drag.startY;
    if (!drag.committed) {
      if (Math.hypot(rawDx, dy) < 10) return;
      if (Math.abs(dy) > Math.abs(rawDx) * 1.2) {
        drag.active = false;
        return;
      }
      drag.committed = true;
      cardRef.current?.setPointerCapture(event.pointerId);
      if (cardRef.current) cardRef.current.dataset.dragging = "true";
    }
    const maxTravel = drag.width * 0.55;
    const clamped =
      Math.abs(rawDx) > maxTravel
        ? Math.sign(rawDx) *
          (maxTravel + rubberband(Math.abs(rawDx) - maxTravel, drag.width * 0.45))
        : rawDx;
    drag.currentX = clamped;
    const now = performance.now();
    drag.history.push({ x: clamped, t: now });
    if (drag.history.length > 6) drag.history.shift();
    spring.setImmediate(clamped);
  }

  function finishDrag(event: PointerEvent<HTMLDivElement>) {
    const drag = dragRef.current;
    if (!drag || event.pointerId !== drag.pointerId) return;
    dragRef.current = null;
    if (cardRef.current) {
      delete cardRef.current.dataset.dragging;
      if (cardRef.current.hasPointerCapture(event.pointerId)) {
        cardRef.current.releasePointerCapture(event.pointerId);
      }
    }
    if (!drag.committed) return;

    const now = performance.now();
    const recent = drag.history.find((sample) => now - sample.t <= 90) ?? drag.history[0];
    const dt = recent ? Math.max((now - recent.t) / 1000, 0.016) : 0.05;
    const velocity = recent ? (drag.currentX - recent.x) / dt : 0;
    const projected = drag.currentX + projectMomentum(velocity, 0.992);
    const threshold = drag.width * 0.28;

    if (Math.abs(projected) > threshold) {
      const delta = projected < 0 ? 1 : -1;
      const entryOffset = projected < 0 ? 54 : -54;
      go(delta, entryOffset, velocity * 0.2);
    } else {
      spring.setTarget(0, { config: SPRING_UI, velocity, reduceMotion });
    }
  }

  if (!card) {
    return <p className="empty-state">No cards are available for this specimen.</p>;
  }

  return (
    <div className="cards-layout">
      <div className="flashcard-stack">
        <div className="flashcard-stack__layer flashcard-stack__layer--2" aria-hidden="true" />
        <div className="flashcard-stack__layer flashcard-stack__layer--1" aria-hidden="true" />
        <div
          ref={cardRef}
          className={`flashcard${flipped ? " flashcard--flipped" : ""}`}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={finishDrag}
          onPointerCancel={finishDrag}
        >
          <div className="flashcard__meta">
            <span className="eyebrow">{flipped ? "Reviewed answer" : "Structure"}</span>
            <span className="pill">
              {index + 1} / {cards.length}
            </span>
          </div>
          {flipped ? (
            <div key={`${card.structureId}:back`} className="flashcard__back">
              <h2>{card.front}</h2>
              <p className="preserve-lines">{card.back}</p>
              <p className="fact__cite">
                <a href={card.citation.url} target="_blank" rel="noreferrer noopener">
                  <span>
                    {card.citation.sourceTitle} · {card.citation.locator}
                  </span>
                  <IconArrowUpRight />
                </a>
              </p>
            </div>
          ) : (
            <div key={`${card.structureId}:front`} className="flashcard__front">
              <h2>{card.front}</h2>
              <p className="muted">
                Say or write what this structure does, then reveal the reviewed answer.
              </p>
            </div>
          )}
          <div className="flashcard__actions">
            <button type="button" className="button button--ghost" onClick={() => go(-1, -44, 0)}>
              Previous
            </button>
            <button
              type="button"
              className="button button--primary"
              aria-pressed={flipped}
              onClick={() => {
                const nextFlipped = !flipped;
                setFlipped(nextFlipped);
                if (nextFlipped) {
                  appStore.getState().markStructureViewed(specimen.id, card.structureId);
                }
              }}
            >
              {flipped ? "Hide answer" : "Reveal answer"}
            </button>
            <button type="button" className="button button--ghost" onClick={() => go(1, 44, 0)}>
              Next
            </button>
          </div>
        </div>
      </div>

      <aside className="study-aside">
        <h2>How to use this deck</h2>
        <p>
          Cards are built directly from structure summaries and cited facts. Revealing a card counts
          the structure as explored; drag a card sideways or use Previous / Next to cycle.
        </p>
        <p className="muted small">
          Deck size: {cards.length} cards. Nothing is sent over the network.
        </p>
        <a
          className="button button--ghost"
          href={previewUrl(specimen.previewPath)}
          target="_blank"
          rel="noreferrer noopener"
        >
          <span>Open full preview</span>
          <IconArrowUpRight />
        </a>
      </aside>
    </div>
  );
}

function QuizPanel({ specimenId }: { specimenId: string }) {
  const specimen = requireSpecimen(specimenId);
  const questions = useMemo(() => buildQuiz(REGISTRY, specimen.id, { count: 5 }), [specimen.id]);
  const [index, setIndex] = useState(0);
  const [chosen, setChosen] = useState<string | null>(null);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);
  const question = questions[index];

  function answer(questionItem: QuizQuestion, optionId: string) {
    if (chosen) return;
    setChosen(optionId);
    const correct = optionId === questionItem.correctOptionId;
    if (correct) setScore((value) => value + 1);
    appStore.getState().answerQuestion({
      specimenId: specimen.id,
      structureId: questionItem.structureId,
      questionId: questionItem.id,
      correct,
    });
  }

  function next() {
    if (index + 1 >= questions.length) {
      setFinished(true);
      return;
    }
    setIndex((value) => value + 1);
    setChosen(null);
  }

  function restart() {
    setIndex(0);
    setChosen(null);
    setScore(0);
    setFinished(false);
  }

  if (questions.length === 0) {
    return <p className="empty-state">No cited questions are available for this specimen.</p>;
  }

  if (finished) {
    const percent = Math.round((score / questions.length) * 100);
    return (
      <div className="quiz-result">
        <p className="eyebrow">Round complete</p>
        <h2>
          {score} of {questions.length} correct ({percent}%)
        </h2>
        <p>
          {percent >= 80
            ? "Strong recall. Open the structure list anytime to review the cited source locators in full."
            : "Mastery grows from revisiting the cited facts. Try the deck, then run another round."}
        </p>
        <div className="quiz-result__actions">
          <button type="button" className="button button--primary" onClick={restart}>
            Another round
          </button>
          <button
            type="button"
            className="button button--ghost"
            onClick={() => {
              const first = specimen.structures[0];
              if (first) navigateToStructure(specimen.id, first.id);
            }}
          >
            Read the structures
          </button>
        </div>
      </div>
    );
  }

  if (!question) return null;

  return (
    <div className="quiz">
      <div className="quiz__head">
        <p className="eyebrow">
          Question {index + 1} of {questions.length}
        </p>
        <span className="pill">Score {score}</span>
      </div>
      <p className="quiz__prompt preserve-lines">{question.prompt}</p>
      <ul className="quiz__options">
        {question.options.map((option, optionIndex) => {
          const isCorrect = option.id === question.correctOptionId;
          const isChosen = option.id === chosen;
          const state = !chosen
            ? ""
            : isCorrect
              ? " is-correct"
              : isChosen
                ? " is-wrong"
                : " is-muted";
          return (
            <li key={option.id}>
              <button
                type="button"
                className={`quiz-option${state}`}
                disabled={chosen !== null}
                onClick={() => answer(question, option.id)}
              >
                <span className="quiz-option__key" aria-hidden="true">
                  {String.fromCharCode(65 + optionIndex)}
                </span>
                <span className="quiz-option__label">{option.label}</span>
                {chosen && isCorrect && (
                  <span className="quiz-option__icon" aria-hidden="true">
                    <IconCheck />
                  </span>
                )}
                {chosen && isChosen && !isCorrect && (
                  <span className="quiz-option__icon" aria-hidden="true">
                    <IconX />
                  </span>
                )}
              </button>
            </li>
          );
        })}
      </ul>

      {chosen && (
        <div className="quiz__feedback" role="status" aria-live="polite">
          <p
            className={
              chosen === question.correctOptionId
                ? "feedback feedback--ok"
                : "feedback feedback--bad"
            }
          >
            {chosen === question.correctOptionId
              ? "Correct."
              : "That is not the structure named in the reviewed statement."}
          </p>
          <p>{question.explanation}</p>
          <p className="fact__cite">
            <a href={question.citation.url} target="_blank" rel="noreferrer noopener">
              {question.citation.sourceTitle} · {question.citation.locator}
            </a>
          </p>
          <button type="button" className="button button--primary" onClick={next}>
            {index + 1 >= questions.length ? "See result" : "Next question"}
          </button>
          <p className="muted small">
            This answer updates unique-question progress for {specimen.name}. Correcting a wrong
            answer later replaces the earlier record.
          </p>
        </div>
      )}
    </div>
  );
}

function TutorPanel({ specimenId }: { specimenId: string }) {
  const specimen = requireSpecimen(specimenId);
  const liveTutorEnabled = useVanillaStore(appStore, (state) => state.settings.liveTutorEnabled);
  const liveTutorConsent = useVanillaStore(appStore, (state) => state.settings.liveTutorConsent);
  const staticTutor = useMemo(() => createStaticTutor(REGISTRY), []);
  const endpoint = (import.meta.env.VITE_TUTOR_ENDPOINT as string | undefined)?.trim() || null;
  const remote = useMemo(
    () =>
      createRemoteTutor({
        endpoint,
        enabled: liveTutorEnabled,
        consent: liveTutorConsent,
        registry: REGISTRY,
      }),
    [endpoint, liveTutorEnabled, liveTutorConsent],
  );
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState<TutorAnswer | null>(null);
  const [busy, setBusy] = useState(false);
  const [consentChecked, setConsentChecked] = useState(liveTutorConsent);
  const exampleStructure = specimen.structures[0]?.name.toLowerCase() ?? "structure";
  const publishers = useMemo(
    () => [...new Set(REGISTRY_SOURCES.map((source) => source.publisher))].join(", "),
    [],
  );

  async function ask() {
    const prompt = question.trim();
    if (!prompt || busy) return;
    setBusy(true);
    setAnswer(null);
    try {
      const provider = remote.isAvailable() ? remote : staticTutor;
      const result = await provider.ask({ question: prompt, specimenId: specimen.id });
      setAnswer(result);
    } catch {
      setAnswer({
        kind: "refusal",
        reason: "error",
        providerId: remote.isAvailable() ? "remote" : "static-facts",
        message: "The study helper encountered an error. Please try again.",
      });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="tutor-layout">
      <div className="tutor-chat">
        <div className="tutor-chat__head">
          <div>
            <p className="eyebrow">
              {remote.isAvailable() ? "Live provider" : "Offline cited helper"}
            </p>
            <h2>Ask about {specimen.shortName}</h2>
          </div>
          <span className={`pill ${remote.isAvailable() ? "pill--warn" : ""}`}>
            {remote.isAvailable() ? "Network on" : "Local only"}
          </span>
        </div>

        <label className="field">
          <span>Your question</span>
          <textarea
            value={question}
            onChange={(event) => setQuestion(event.target.value)}
            onKeyDown={(event) => {
              if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
                event.preventDefault();
                void ask();
              }
            }}
            rows={4}
            maxLength={500}
            placeholder={`e.g. What does the ${exampleStructure} do?`}
          />
        </label>
        <div className="tutor-suggestions" role="group" aria-label="Suggested questions">
          {specimen.structures.slice(0, 3).map((candidate) => {
            const promptText = `What does the ${candidate.name.toLowerCase()} do?`;
            return (
              <button
                key={candidate.id}
                type="button"
                className="chip"
                onClick={() => setQuestion(promptText)}
              >
                {promptText}
              </button>
            );
          })}
        </div>
        <div className="tutor-chat__actions">
          <button
            type="button"
            className="button button--primary"
            onClick={() => void ask()}
            disabled={busy || !question.trim()}
          >
            {busy ? "Checking…" : "Ask"}
          </button>
          <p className="muted small">
            {remote.isAvailable()
              ? "Your question and selected specimen are sent to the configured provider."
              : "The offline helper only matches reviewed statements. Nothing leaves this browser."}
          </p>
        </div>

        <div className="tutor-answer" aria-live="polite">
          {busy && <p role="status">Looking for a reviewed statement…</p>}
          {answer?.kind === "answer" && (
            <>
              <p>{answer.text}</p>
              <ul className="tutor-citations">
                {answer.citations.map((citation, index) => (
                  <li key={`${citation.sourceId}-${index}`}>
                    <a href={citation.url} target="_blank" rel="noreferrer noopener">
                      {citation.sourceTitle} · {citation.locator}
                    </a>
                    {citation.statement && <p className="muted small">{citation.statement}</p>}
                  </li>
                ))}
              </ul>
            </>
          )}
          {answer?.kind === "refusal" && (
            <div className="feedback feedback--neutral">
              <p>{answer.message}</p>
              <p className="muted small">Reason: {answer.reason}. This refusal is deliberate.</p>
            </div>
          )}
        </div>
      </div>

      <aside className="study-aside">
        <h2>Live tutor is opt-in</h2>
        <p>
          Live tutoring is off by default and unavailable in this build unless a reviewed HTTPS
          endpoint is configured.
        </p>
        {endpoint ? (
          <>
            <label className="checkbox">
              <input
                type="checkbox"
                checked={consentChecked}
                onChange={(event) => setConsentChecked(event.target.checked)}
              />
              <span>
                I understand my question and the selected specimen ID will be sent to the configured
                provider, and that provider retention is outside this app.
              </span>
            </label>
            <button
              type="button"
              className="button button--ghost"
              disabled={!consentChecked && !liveTutorEnabled}
              onClick={() => {
                const enabled = !liveTutorEnabled;
                appStore.getState().setLiveTutor({ enabled, consent: consentChecked });
              }}
            >
              {liveTutorEnabled ? "Turn live tutor off" : "Enable live tutor"}
            </button>
          </>
        ) : (
          <p className="callout">
            No tutor endpoint is configured in this build. The local helper is the only provider.
          </p>
        )}
        <h3>What is never stored</h3>
        <p className="muted small">
          Prompts and answers are kept in memory for this tab only. They are not written to
          IndexedDB and are not included in progress exports.
        </p>
        <p className="muted small">
          Static answers quote at most two reviewed statements for the matched structure. Sources:{" "}
          {publishers}.
        </p>
      </aside>
    </div>
  );
}

function ProgressPanel() {
  const profile = useVanillaStore(appStore, (state) => state.profile);
  const persistence = usePersistence();
  const summaries = REGISTRY_SPECIMENS.map((specimen) => ({
    specimen,
    summary: summarizeProgress(profile, specimen.id, specimen.structures.length),
  }));
  const favorites = profile.favorites.flatMap((favorite) => {
    const [specimenId, structureId] = favorite.split(":");
    if (!specimenId || !structureId) return [];
    const specimen = REGISTRY_SPECIMENS.find((candidate) => candidate.id === specimenId);
    const structure = specimen?.structures.find((candidate) => candidate.id === structureId);
    if (!specimen || !structure) return [];
    return [{ specimen, structure }];
  });

  return (
    <div className="progress-panel">
      <div className="progress-panel__main">
        <h2>Local mastery</h2>
        <p className="muted small">
          Mastery is half structure exploration and half unique-question accuracy. It is a study
          aid, not an assessment or credential.{" "}
          {persistence.status === "memory" || persistence.status === "error"
            ? "This session is not being saved."
            : "Progress saves in this browser profile."}
        </p>
        <ul className="mastery-list">
          {summaries.map(({ specimen, summary }) => (
            <li key={specimen.id} className="mastery-list__item">
              <img
                className="mastery-list__thumb"
                src={previewUrl(specimen.previewPath)}
                alt=""
                width={44}
                height={44}
                loading="lazy"
                decoding="async"
              />
              <div className="mastery-list__body">
                <div className="mastery-list__row">
                  <button
                    type="button"
                    className="link-button"
                    onClick={() => appStore.getState().selectSpecimen(specimen.id)}
                  >
                    {specimen.name}
                  </button>
                  <span>{summary.mastery}%</span>
                </div>
                <div className="progress progress--wide">
                  <span style={{ width: `${summary.mastery}%` }} />
                </div>
                <p className="muted small">
                  {summary.structuresViewed}/{summary.structuresTotal} structures ·{" "}
                  {summary.questionsCorrect}/{summary.questionsAnswered} correct
                  {summary.completed ? " · round complete" : ""}
                </p>
              </div>
            </li>
          ))}
        </ul>
      </div>

      <aside className="study-aside">
        <h2>Saved structures</h2>
        {favorites.length === 0 ? (
          <p className="muted">No favourites yet. Use “Save” on a structure detail page.</p>
        ) : (
          <ul className="favorite-list">
            {favorites.map(({ specimen, structure }) => (
              <li key={`${specimen.id}:${structure.id}`}>
                <button
                  type="button"
                  className="link-button"
                  onClick={() => navigateToStructure(specimen.id, structure.id)}
                >
                  {structure.name}
                </button>
                <span className="muted small">{specimen.name}</span>
              </li>
            ))}
          </ul>
        )}
        <button
          type="button"
          className="button button--ghost"
          onClick={() => {
            if (
              window.confirm(
                "Reset local learning progress for every specimen? This cannot be undone.",
              )
            ) {
              appStore.getState().resetProgress();
            }
          }}
        >
          Reset learning progress
        </button>
        <p className="muted small">
          Storage: {persistence.adapterKind ?? "checking"}. Export and delete controls live in
          About.
        </p>
      </aside>
    </div>
  );
}
