import type { Registry, Specimen, Structure } from "@cas/content-registry";

export type QuizOption = { id: string; label: string };

export type QuizQuestion = {
  id: string;
  specimenId: string;
  structureId: string;
  prompt: string;
  options: QuizOption[];
  correctOptionId: string;
  explanation: string;
  citation: {
    sourceId: string;
    sourceTitle: string;
    locator: string;
    url: string;
  };
};

export type Flashcard = {
  id: string;
  specimenId: string;
  structureId: string;
  front: string;
  back: string;
  citation: {
    sourceId: string;
    sourceTitle: string;
    locator: string;
    url: string;
  };
};

function hash(value: string): number {
  let result = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    result ^= value.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  return result >>> 0;
}

function deterministicOrder<T>(values: T[], key: (value: T) => string): T[] {
  return [...values].sort((a, b) => {
    const delta = hash(key(a)) - hash(key(b));
    return delta !== 0 ? delta : key(a).localeCompare(key(b));
  });
}

function sourceFor(registry: Registry, sourceId: string) {
  const source = registry.sources.find((candidate) => candidate.id === sourceId);
  if (!source) throw new Error(`Quiz references unknown source ${sourceId}`);
  return source;
}

/**
 * Builds questions only from authored, cited facts. The correct answer is a
 * structure in the same specimen, and the explanation repeats the reviewed
 * statement rather than generating new biology.
 */
export function buildQuiz(
  registry: Registry,
  specimenId: string,
  options: { count?: number } = {},
): QuizQuestion[] {
  const specimen = registry.specimens.find((candidate) => candidate.id === specimenId);
  if (!specimen) return [];
  const count = Math.max(1, Math.min(options.count ?? 4, 8));

  const factEntries = specimen.structures.flatMap((structure) =>
    structure.facts.map((fact) => ({ structure, fact })),
  );
  const ordered = deterministicOrder(factEntries, (entry) => entry.fact.id).slice(0, count);

  return ordered.map(({ structure, fact }) => {
    const source = sourceFor(registry, fact.sourceId);
    const distractors = deterministicOrder(
      specimen.structures.filter((candidate) => candidate.id !== structure.id),
      (candidate) => `${fact.id}:${candidate.id}`,
    ).slice(0, 3);
    const optionStructures: Structure[] = [structure, ...distractors];
    const shuffled = deterministicOrder(
      optionStructures,
      (candidate) => `option:${fact.id}:${candidate.id}`,
    );

    return {
      id: `quiz:${specimenId}:${fact.id}`,
      specimenId,
      structureId: structure.id,
      prompt: `Which structure does this reviewed statement describe?\n\n“${fact.statement}”`,
      options: shuffled.map((candidate) => ({ id: candidate.id, label: candidate.name })),
      correctOptionId: structure.id,
      explanation: `This statement is filed under ${structure.name}. It comes from ${source.publisher}, ${source.edition}, ${fact.locator}.`,
      citation: {
        sourceId: source.id,
        sourceTitle: source.title,
        locator: fact.locator,
        url: source.url,
      },
    };
  });
}

export function buildFlashcards(registry: Registry, specimen: Specimen): Flashcard[] {
  const cards: Flashcard[] = [];
  for (const structure of specimen.structures) {
    const primaryFact = structure.facts[0];
    if (!primaryFact) continue;
    const source = sourceFor(registry, primaryFact.sourceId);
    cards.push({
      id: `card:${specimen.id}:${structure.id}`,
      specimenId: specimen.id,
      structureId: structure.id,
      front: structure.name,
      back: `${structure.summary}\n\nKey fact: ${primaryFact.statement}`,
      citation: {
        sourceId: source.id,
        sourceTitle: source.title,
        locator: primaryFact.locator,
        url: source.url,
      },
    });
  }
  return cards;
}

export function buildDeck(registry: Registry): Flashcard[] {
  return registry.specimens.flatMap((specimen) => buildFlashcards(registry, specimen));
}
